const body = $json.body ?? $json;
const slug = (body.project_slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('project_slug is required in the JSON body.');
const burnRaw = (body.burn_subs ?? 'yes').toString();
const fontRaw = Number(body.subtitle_font_size ?? 24);
const volRaw = Number(body.music_volume ?? 0.15);
return [{ json: {
  slug,
  burn_subs: burnRaw === 'yes',
  font_size: Math.min(64, Math.max(10, Number.isFinite(fontRaw) && fontRaw > 0 ? fontRaw : 24)),
  music_file: (body.music_file ?? '').toString(),
  music_volume: Number.isFinite(volRaw) && volRaw > 0 ? volRaw : 0.15,
}}];

const plan = $json;
function srtTime(sec) {
  const ms = Math.max(0, Math.round(sec * 1000));
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  const milli = ms % 1000;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(milli).padStart(3, '0')}`;
}
let t = 0;
const cues = [];
for (const shot of plan.shots) {
  const start = t;
  const end = t + shot.dur;
  t = end;
  const text = (shot.subtext ?? '').toString().trim();
  if (!text) continue;
  cues.push(`${cues.length + 1}\n${srtTime(start)} --> ${srtTime(end)}\n${text}\n`);
}
return [{ json: { slug: plan.slug, plan, srt: cues.join('\n') } }];
